package oepul.o6_2

import rego.v1

t := data.o6_2_tables
year := input.farm.year
app := input.farm.application

contract := row if {
	some row in t.contracts
	row.start_year == app.start_year
}

valid_date(d) if {
	regex.match(`^[0-9]{4}-[0-9]{2}-[0-9]{2}$`, d)
	is_number(time.parse_rfc3339_ns(concat("", [d, "T00:00:00Z"])))
}

entry_on_time if {
	valid_date(app.application_date)
	app.application_date < contract.start
}

bio_compatible if app.bio_scope == "none"

bio_compatible if {
	app.bio_scope == "wine_fruit_hops"
	app.separate_units
	app.separate_crop_sectors
	app.separate_stores
}

combination_ok if {
	app.ubb
	bio_compatible
}

switch_allowed if {
	some row in t.switches
	row.from == "2"
	row.to == app.switch_to
	valid_date(app.switch_date)
	contract.start <= app.switch_date
	app.switch_date <= sprintf("%d-12-31", [row.through])
}

applicant_ok if {
	a := input.farm.applicant
	a.legal_form in t.applicant_forms
	a.public_control == false
	is_number(a.public_share_pct)
	a.public_share_pct <= 25
	a.active_farmer
	a.agricultural_activity
	a.own_name_and_account
	a.disposal_right
}

minimum_size_ok if year > app.first_oepul_year

minimum_size_ok if {
	year == app.first_oepul_year
	input.land.protected_cultivation_at_ha >= 0.5
}

minimum_size_ok if {
	year == app.first_oepul_year
	input.land.mfa_minimum_size_area_at_ha >= 1.5
}

access_consequence(first_year) := "kein Vertrag" if first_year == true
access_consequence(first_year) := "keine Jahresprämie" if first_year == false

forage_crop(name) if {
	some crop in t.forage_crops
	lower(name) == lower(crop)
}

crop_label(p, "Getreide") if p.crop.crop_name in t.cereals
crop_label(p, "Kein Getreide") if p.crop.crop_name in t.non_cereals

crop_label(p, "Kein Getreide") if {
	p.crop.crop_name == "Gemenge"
	p.crop.cereal_share_pct < 50
}

crop_label(p, "Feldgemüse") if p.crop.crop_name in t.vegetables
crop_label(p, "Ackerfutter") if forage_crop(p.crop.crop_name)
crop_label(p, "Obst") if year >= t.fruit_since[p.crop.crop_name]

crop_label(p, "Obst") if {
	p.crop.crop_name == "Walnüsse"
	year >= t.fruit_since.Walnuss
}

crop_classes(p) := {label |
	some label in {"Getreide", "Kein Getreide", "Feldgemüse", "Ackerfutter", "Obst"}
	crop_label(p, label)
}

tariff_group(p) := "grassland" if p.land_use == "grassland"

tariff_group(p) := "forage" if {
	p.land_use == "arable"
	forage_crop(p.crop.crop_name)
	p.crop.is_second_crop == false
}

known_nonforage(p) if {
	is_string(p.crop.crop_name)
	not forage_crop(p.crop.crop_name)
}

known_nonforage(p) if {
	p.crop.crop_category in {"cereal", "maize", "oilseed", "root", "vegetable"}
	not forage_crop(p.crop.crop_name)
}

tariff_group(p) := "arable" if {
	p.land_use == "arable"
	known_nonforage(p)
}

tariff_group(p) := "arable" if {
	p.land_use == "arable"
	forage_crop(p.crop.crop_name)
	p.crop.is_second_crop
}

tariff_group(p) := "permanent" if {
	p.land_use == "special_crop"
	p.crop.crop_category in {"vineyard", "hop"}
}

tariff_group(p) := "permanent" if {
	p.land_use == "special_crop"
	p.crop.crop_category == "orchard"
	crop_label(p, "Obst")
}

# MFA-Futterfläche, unabhängig vom Zahlungsantrag für die Maßnahme.
forage_part(p) := 0 if {
	is_string(p.mfa.country)
	p.mfa.country != "AT"
}

else := 0 if p.mfa.declared == false

else := 0 if p.land_use in {"alpine_pasture", "other", "special_crop"}

else := 0 if tariff_group(p) == "arable"

else := p.area_ha if {
	p.mfa.country == "AT"
	p.mfa.declared
	tariff_group(p) in {"forage", "grassland"}
	is_number(p.area_ha)
	p.area_ha >= 0
}

forage_ha := sum(parts) if {
	parcels := input.land.parcels
	is_array(parcels)
	parts := [forage_part(p) | some p in parcels]
	count(parts) == count(parcels)
}

animal_class(g) := "Zwergrind" if {
	g.species == "cattle"
	g.breed in t.dwarf_breeds
}

animal_class(g) := "Rind" if {
	g.species == "cattle"
	is_string(g.breed)
	not g.breed in t.dwarf_breeds
}

animal_class(g) := g.category if {
	g.species == "sheep_goats"
	g.category in {"Schaf", "Ziege"}
}

animal_class(g) := "Kleine Equiden" if {
	g.species == "horses"
	is_number(g.breed_height_m)
	is_number(g.breed_adult_weight_kg)
	g.breed_height_m <= 1.48
	g.breed_adult_weight_kg <= 300
}

animal_class(g) := "Große Equiden" if {
	g.species == "horses"
	g.breed_height_m > 1.48
	is_number(g.breed_height_m)
}

animal_class(g) := "Große Equiden" if {
	g.species == "horses"
	g.breed_adult_weight_kg > 300
	is_number(g.breed_adult_weight_kg)
}

wild_group(g) if {
	g.species == "other"
	g.category in {"Rotwild", "Damwild", "Anderes Zuchtwild", "Neuweltkamel"}
}

animal_class(g) := g.category if {
	wild_group(g)
	g.captive_on_agricultural_land
}

assessment_count(g) := g.annual_mean_count if {
	g.species == "cattle"
	g.count_basis == "cattle_database_daily"
	is_number(g.annual_mean_count)
}

assessment_count(g) := g.annual_mean_count if {
	g.species != "cattle"
	g.count_basis == "average_list"
	is_number(g.annual_mean_count)
}

assessment_count(g) := g.animal_count if {
	g.species != "cattle"
	g.count_basis == "april_1"
	g.fluctuating_stock == false
	is_number(g.animal_count)
}

below_upper(_, upper) if upper == null
below_upper(value, upper) if value < upper

pig_gve_per_head(category) := row.gve_per_head if {
	some row in t.pig_gve
	row.category == category
}

hundredths_rgve(g) := 0 if {
	is_string(g.country)
	g.country != "AT"
}

else := 0 if g.species in {"poultry", "rabbits"}

else := 0 if g.species == "pigs"

else := 0 if {
	g.species == "other"
	g.category == "Sonstige Nicht-RGVE"
}

else := 0 if {
	wild_group(g)
	g.captive_on_agricultural_land == false
}

else := n * round(row.rgve_per_head * 100) if {
	g.country == "AT"
	n := assessment_count(g)
	n >= 0
	some row in t.rgve_factors
	row.group == animal_class(g)
	is_number(g.age_months)
	g.age_months >= row.age_months_from
	below_upper(g.age_months, row.age_months_below)
}

animal_contribution(g) := hundredths_rgve(g) / 100

herd_hundredths := sum(parts) if {
	groups := input.livestock.species_groups
	is_array(groups)
	parts := [hundredths_rgve(g) | some g in groups]
	count(groups) == count(parts)
}

rgve := herd_hundredths / 100
density := herd_hundredths / (forage_ha * 100) if forage_ha > 0

# Amtliche RGVE-Faktoren haben höchstens zwei Dezimalstellen. Direktvergleich
# in Hundertsteln vermeidet eine Grenzentscheidung aus einem gerundeten Quotienten.
stock_band := "none" if {
	forage_ha > 0
	herd_hundredths < forage_ha * 30
}

else := "medium" if {
	forage_ha > 0
	herd_hundredths < forage_ha * 140
}

else := "high" if {
	forage_ha > 0
	herd_hundredths >= forage_ha * 140
}

tariff_band(group) := "all" if group in {"arable", "permanent"}
tariff_band(group) := stock_band if group in {"grassland", "forage"}

npf_crop(name) if {
	some crop in t.npf_crops
	lower(name) == lower(crop)
}

npf_exclusion(p) if {
	year <= 2024
	tariff_group(p) == "forage"
	npf_crop(p.crop.crop_name)
	"NPF" in p.mfa.codes
}

rate(p) := 0 if {
	year >= 2023
	npf_exclusion(p)
}

else := row.eur_per_ha if {
	some row in t.premium_rates
	row.year_from <= year
	year <= row.year_to
	row.group == tariff_group(p)
	row.stock_band == tariff_band(row.group)
	npf_resolved(p)
}

npf_resolved(_) if year >= 2025
npf_resolved(p) if tariff_group(p) != "forage"

npf_resolved(p) if {
	is_string(p.crop.crop_name)
	not npf_crop(p.crop.crop_name)
}

npf_resolved(p) if is_array(p.mfa.codes)

# Jahressätze vor Modulation, Deckelung, Sanktionen und Kombinationsausschlüssen.
base_rates[p.parcel_id] := rate(p) if some p in input.land.parcels

combination_row(measure) := row.cells if {
	some row in t.combination_matrix
	row.measure == measure
}

combination_cell(left, right) := combination_row(left)[right]
combination_note(id) := t.combination_notes[id]

groundwater_base(base) := base * 0.5 if {
	base >= 0
	combination_cell("2", "16") == "a"
}

exclusion(p, "Ausland") if {
	is_string(p.mfa.country)
	p.mfa.country != "AT"
}

exclusion(p, "MFA") if p.mfa.claimed_o6_2 == false
exclusion(p, "MFA") if p.mfa.correctly_identified == false
exclusion(p, "Nutzung") if p.mfa.use in t.excluded_uses
exclusion(p, "Landwirtschaft") if p.mfa.predominantly_agricultural == false
exclusion(p, "GLÖZ-LSE") if p.mfa.gloez_lse
exclusion(p, "Nationalpark") if p.mfa.national_park in {"Neusiedlersee", "Donau-Auen"}
exclusion(p, "Nationalpark") if p.mfa.relevant_park_restrictions
exclusion(p, "Versuchsfläche") if "VF" in p.mfa.codes
exclusion(p, "Versuchsfläche") if p.mfa.approved_trial_precludes_obligation
exclusion(p, "OP") if "OP" in p.mfa.codes
exclusion(p, "OP") if p.mfa.op_for_o6_2

exclusion(p, "Obstqualität") if {
	p.crop.crop_category == "orchard"
	p.crop.high_quality_stock == false
}

exclusion(p, "Kombination") if {
	some m in p.mfa.other_parcel_measures
	m != "2"
	combination_cell("2", m) == ""
}

exclusion(p, "Sonderfläche") if p.mfa.ubb_arable_div
exclusion(p, "Sonderfläche") if p.mfa.protected_pots_or_substrate

exclusion(p, "Sonderfläche") if {
	some c in p.mfa.codes
	c in {"BAW", "AG", "K20"}
}

parcel_exclusions[p.parcel_id] contains reason if {
	some p in input.land.parcels
	some reason in {"Ausland", "MFA", "Nutzung", "Landwirtschaft", "GLÖZ-LSE", "Nationalpark", "Versuchsfläche", "OP", "Obstqualität", "Kombination", "Sonderfläche"}
	exclusion(p, reason)
}

package oepul.o6_2

import rego.v1

eligible_size_use(use) if {
	use in t.size_eligible_uses
	use != "K20 auf NF"
	use != "Agroforststreifen"
}

eligible_size_use("K20 auf NF") if year <= 2024
eligible_size_use("Agroforststreifen") if year >= 2025
reduction_order := t.reduction_order

special_management(p) if {
	some row in t.minimum_management_exceptions
	row.use == p.mfa.management_exception
	year <= row.through
	some m in p.mfa.parcel_measures
	m in row.measures
	year_valid_measure(m)
}

year_valid_measure(m) if m != "1C"
year_valid_measure("1C") if year >= 2025

permanent_management_ok(p) if {
	p.land_use == "special_crop"
	p.operations.harvest.proper_planting
	p.operations.harvest.annual_care
	p.operations.harvest.harvested_and_removed
}

forage_management_ok(p) if {
	sensitive(p)
	p.operations.harvest.full_cut_removed_this_year
}

forage_management_ok(p) if {
	sensitive(p)
	p.operations.harvest.full_grazing_this_year
}

forage_management_ok(p) if {
	sensitive(p)
	p.mfa.mountain_meadow
	p.operations.harvest.full_cut_removed_last_year
}

retired_cover_ok(p) if p.operations.harvest.proper_green_cover

retired_cover_ok(p) if {
	p.mfa.management_exception == "Nichtproduktive Ackerfläche"
	"1C" in p.mfa.parcel_measures
	year >= 2025
	p.operations.harvest.self_greened
}

retired_management_ok(p) if {
	p.mfa.out_of_production
	retired_cover_ok(p)
	p.operations.harvest.mulched_or_care_cut_in_two_years
}

op_reason(p, "Ernte") if {
	p.mfa.harvest_duty
	p.operations.harvest.harvest_duty_failed
	p.operations.harvest.individual_force_majeure_approved == false
	not drought_waiver(p)
}

op_reason(p, "Öffentliche Leistungsüberschneidung") if p.mfa.overlap_public
op_reason(p, "Behördlicher Ausgleich") if p.mfa.mandated_compensation_or_infrastructure
op_reason(p, "Laufzeit") if p.mfa.can_complete_commitment == false
op_reason(p, "Weitergabe") if p.mfa.transfer_without_continuation
op_reason(p, "Fremdverschulden") if p.mfa.exclusively_third_party_breach

op_reason(p, "Obstqualität") if {
	p.crop.crop_category == "orchard"
	p.crop.high_quality_stock == false
}

op_reasons[p.parcel_id] contains reason if {
	some p in input.land.parcels
	some reason in {"Ernte", "Öffentliche Leistungsüberschneidung", "Behördlicher Ausgleich", "Laufzeit", "Weitergabe", "Fremdverschulden", "Obstqualität"}
	op_reason(p, reason)
}

fertilizer_legal_issue(p) if {
	p.mfa.country == "AT"
	p.mfa.agricultural_area
	p.operations.fertilizer.legal_limits_and_periods_met == false
}

missing_psm_codes[p.parcel_id] contains c if {
	some p in input.land.parcels
	p.mfa.country == "AT"
	is_array(p.mfa.codes)
	some c in required_psm_codes(p)
	not c in p.mfa.codes
}

psm_update_due(p) if {
	year >= 2023
	year <= 2025
	sensitive(p)
	p.mfa.planned_psm_cancelled_or_changed
}

ubb_hours_ok if input.documentation.credited_ubb_biodiversity_hours >= 3
div_minimum_ha(area) := area * 0.07 if area > 2

else := 0 if {
	area >= 0
	area <= 2
}

# Teilprüfung der UBB-/BIO-Ausnahme. Auflagen der Projektbestätigung sind vorrangig.
div_op(p) if {
	some c in p.mfa.codes
	c in {"OPUBB", "OPBIO"}
}

early_arable_div(p) if {
	year == 2026
	p.land_use == "arable"
	p.mfa.ubb_arable_div
	p.mfa.other_use_restrictions == false
	div_op(p)
}

third_div_use(p) if {
	early_arable_div(p)
	p.operations.div_uses_this_year == 3
}

annual_div_mowing(p) if {
	p.land_use == "grassland"
	some code in t.div_codes
	code in p.mfa.codes
	p.operations.harvest.cut_and_removed_at_least_once
}

div_rest_days(p) := 49 if {
	year == 2026
	"DIVNFZ" in p.mfa.codes
	div_op(p)
	p.mfa.other_use_restrictions == false
}

else := 7 * div_variant("DIVNFZ").rest_weeks if "DIVNFZ" in p.mfa.codes

field_div_minimum(relevant_farm_ha, field_block_ha) := 0.15 if {
	relevant_farm_ha >= 10
	field_block_ha > 5
}

else := 0 if {
	is_number(relevant_farm_ha)
	is_number(field_block_ha)
}

div_2026_example(state) := row if {
	some row in t.district_div_early_examples
	row.state == state
}

parcel_combinations[m] := {"measure": t.measure_names[m], "marker": marker} if {
	some m, marker in combination_row("2")
	m != "2"
}

commitment_class(id) := "mehrjährig" if id in t.multiyear_contracts

commitment_class(id) := "einjährig" if {
	id in t.annual_contracts
	year_valid_measure(id)
}

annually_variable(id) if id in t.annual_units
special_takeover(id) if id in t.special_takeovers

public_body_exception(id) if {
	some r in t.public_body_exceptions
	r.measure == id
	r.year_from <= year
	year <= r.year_to
}

stock_loss_effect(previous_density) := {"earlier_payments_recovered_for_status_change": false, "obligations_continue": true} if {
	previous_density >= 0.30
	stock_band == "none"
}

known_incompatibility if app.ubb == false
known_incompatibility if app.bio_scope in {"whole_farm", "other_partial"}

known_incompatibility if {
	app.bio_scope == "wine_fruit_hops"
	some f in ["separate_units", "separate_crop_sectors", "separate_stores"]
	app[f] == false
}

missing_combination_consequence := access_consequence(year == app.start_year) if {
	known_incompatibility
	contract.start_year <= year
	year <= 2028
}

# Bei gleichem Kalendertag ist die Uhrzeit für die Reihenfolge entscheidend.
before_or_unset(_, end) if end == null

before_or_unset(d, end) if {
	valid_date(end)
	d < end
}

exit_before_control if {
	proceedings := input.documentation.proceedings
	valid_date(proceedings.withdrawal_date)
	before_or_unset(proceedings.withdrawal_date, proceedings.onsite_announced_or_started)
	before_or_unset(proceedings.withdrawal_date, proceedings.administrative_result_received)
}

correction_window_open if {
	proceedings := input.documentation.proceedings
	proceedings.impossible_combination_requested
	proceedings.control_objection == false
	proceedings.payment_notification_received == null
}

third_party_evidence_due(p) if {
	p.mfa.exclusively_third_party_breach
	input.documentation.proceedings.third_party_proof_retained == false
}

trial_evidence_due(p) if {
	p.mfa.approved_trial_precludes_obligation
	false in [object.get(input.documentation.proceedings, "trial_approval_retained", null), object.get(input.documentation.proceedings, "trial_type_size_location_recorded", null)]
}

training_at_deadline := "erfüllt" if count(trained_people) > 0

else := "Einzelfallprüfung Stichtag" if {
	is_array(input.documentation.courses)
	some c in input.documentation.courses
	c.left_on == "2025-12-31"
}

else := "Stundennachweis fehlt" if {
	is_array(input.documentation.courses)
	input.documentation.course_history_complete
	year >= 2025
	valid_date(input.documentation.training_assessment_date)
	input.documentation.training_assessment_date >= "2025-12-31"
}

annual_stock_change := stock_loss_effect(input.livestock.previous_rgve_per_forage_ha)

package oepul.o6_2

import rego.v1

# Für jeden Biogasanlagen-Rücklauf sind kumulierte, vergleichbare Mengen zu verwenden.
fertilizer_status(f) := "verboten" if f.kind in {"Klärschlamm", "Anderer organischer Rückstand"}

else := "verboten" if f.kind in t.residue_examples

else := "erlaubt" if {
	f.kind == "Häusliches Abwasser"
	f.external == false
}

else := "erlaubt" if f.kind in t.manures

else := "erlaubt" if {
	f.kind == "Kompost"
	f.eu_organic_allowed
}

else := "erlaubt" if {
	f.kind == "Biogasgülle"
	f.own_slurry_delivered > 0
	is_number(f.own_slurry_delivered)
	is_number(f.cumulative_return)
	f.cumulative_return >= 0
	f.cumulative_return <= f.own_slurry_delivered
}

else := "verboten" if {
	f.kind == "Biogasgülle"
	is_number(f.own_slurry_delivered)
	is_number(f.cumulative_return)
	f.cumulative_return > f.own_slurry_delivered
}

else := "erlaubt" if {
	f.kind == "Einzel-/Mehrnährstoffdünger"
	f.contains_n == false
}

else := "verboten" if {
	f.external
	f.contains_n
	f.kind == "Kompost"
	f.eu_organic_allowed == false
}

else := "verboten" if {
	f.external
	f.contains_n
	f.kind in {"Einzel-/Mehrnährstoffdünger", "Häusliches Abwasser", "Sonstiger Dünger"}
}

else := "erlaubt" if {
	f.external == false
	f.kind in {"Einzel-/Mehrnährstoffdünger", "Sonstiger Dünger", "Kompost"}
}

fertilizer_findings contains {"parcel": p.parcel_id, "index": i, "status": s} if {
	some p in input.land.parcels
	p.mfa.country == "AT"
	p.mfa.agricultural_area
	some i, f in p.operations.fertilizer.applications
	s := fertilizer_status(f)
}

nitrogen_per_ha := net / n.agricultural_ha_at if {
	n := input.livestock.nitrogen
	n.year == year
	n.agricultural_ha_at > 0
	n.livestock_n_at_kg >= 0
	n.housing_storage_loss_kg >= 0
	n.alpine_and_common_grazing_n_kg >= 0
	net := (n.livestock_n_at_kg - n.housing_storage_loss_kg) - n.alpine_and_common_grazing_n_kg
	net >= 0
}

nitrogen_ok := nitrogen_per_ha <= 170

sensitive(p) if p.land_use == "grassland"

sensitive(p) if {
	p.land_use == "arable"
	forage_crop(p.crop.crop_name)
}

area_application(e) if e.method in {"flächig", "Horstbehandlung", "Saatgutbeizung"}

psm_status(p, e) := "verboten" if {
	sensitive(p)
	e.method == "Saatgutbeizung"
}

else := "erlaubt" if {
	sensitive(p)
